mes such as Gyromite.","alternatives":[{"id":"01a21904-ad73-7283-8477-db5a07a4fc4c","description":"Robotic Operating Buddy","correct_answer":true},{"id":"01a21904-ad73-7fe8-a8a4-a571e2795783","description":"Random Object Builder","correct_answer":false},{"id":"01a21904-ad73-755a-be8d-b275708b650b","description":"Realistic Orbital Belt","correct_answer":false},{"id":"01a21904-ad73-72ff-b2a8-92960fbb86ca","description":"Routed Oval Beam","correct_answer":false}]},{"id":"01a21904-ad73-774e-8113-ad4866b4ecbd","category":"01a21312-b489-7d12-a39e-857aff280926","question":"How many swimming lanes are used in an Olympic final?","difficulty":2,"explanation":"Eight swimmers use the central lanes in an Olympic final; the outer lanes are left vacant to reduce turbulence from the walls.","alternatives":[{"id":"01a21904-ad73-7c22-86f2-3e9106ef9393","description":"Eight","correct_answer":true},{"id":"01a21904-ad73-74ac-a898-6745884452ea","description":"Four","correct_answer":false},{"id":"01a21904-ad73-7e85-83e8-9127352e969b","description":"Six","correct_answer":false},{"id":"01a21904-ad73-7798-a92a-f52b5b78b9c3","description":"Ten","correct_answer":false}]},{"id":"01a21904-ad73-7959-b35f-62a43bd92330","category":"01a21312-b489-7d12-a39e-857aff280926","question":"With which sport is Andy Murray associated?","difficulty":2,"explanation":"Andy Murray won Wimbledon\u2019s men\u2019s singles title in 2013 and 2016, ending a 77-year wait for a British champion.","alternatives":[{"id":"01a21904-ad73-72cf-ad2a-4bc500034968","description":"Tennis","correct_answer":true},{"id":"01a21904-ad73-7896-ad8d-38972a429e85","description":"Badminton","correct_answer":false},{"id":"01a21904-ad73-74eb-9b2e-4ac381c49164","description":"Surfing","correct_answer":false},{"id":"01a21904-ad73-75d9-be5e-5be97dad289f","description":"Motor racing","correct_answer":false}]},{"id":"01a21904-ad73-7a37-89ba-d2aa768ba13f","category":"01a21312-b489-7d12-a39e-857aff280926","question":"Which French baron founded the 